    '}',
    '#peak {',
    '  marker-width: 7;',
    '  marker-fill: #3f2a1d;',
    '  marker-line-color: #ffffff;',
    '  marker-line-width: 1.5;',
    '}',
    '#peak::name {',
    '  text-name: [name];',
