#import "MSFExample.h"
#import "MSFPeakFinderSky.h"
#import "MassifMaps.h"
#import "api/MSFMassif.h"
#import "api/MSFMassifMap.h"
#import "api/MSFMassifObject.h"

/**
 * The web peak finder (web/examples/peak-finder.mjs) with the host's buttons in place of its chrome.
 * Shaders and summit CartoCSS are bundle resources, written by scripts/gen-peak-finder-assets.mjs.
 */
@interface MSFPeakFinderExample : NSObject <MSFExample>
@end

static NSString * const kUserAgent =
    @"MassifMapsExamples/1.0 (+https://github.com/massif-maps/MassifMaps)";

/** The ink pass: silhouettes only (operator 2), a heavier skyline. Uniforms left out read zero. */
static NSDictionary<NSString *, NSNumber *> *ink(void) {
    return @{
        @"uOperator": @2, @"uOutlineGain": @12, @"uOutlinePower": @1, @"uOutlineFloor": @0.008,
        @"uOutlineCeiling": @1, @"uOutlineWidth": @1, @"uIntensity": @0.8, @"uHorizonBoost": @0.9,
        @"uHorizonWidth": @2.5, @"uDepthThreshold": @1, @"uCreaseThreshold": @0.12,
        @"uRidgeStrength": @2, @"uRidgeThreshold": @0.05, @"uRidgeGroundSpan": @90,
        @"uDepthTexelSize": @2, @"uGrazingFloor": @0.15, @"uInkDistance": @50000,
        @"uMetersPerUnit": @(40075016.68558 / (1 << 20)), @"uSilhouetteGate": @865,
        @"uHazeDistance": @60000, @"uDistortCenterX": @0.5, @"uDistortCenterY": @0.5,
        @"uDistortScreenTanX": @1, @"uDistortScreenTanY": @1, @"uDistortRenderTanX": @1,
        @"uDistortRenderTanY": @1,
    };
}

/** The surface: ridge ink capped by the light, and a touch of hillshade after the cap. */
static NSDictionary<NSString *, NSNumber *> *surface(void) {
    return @{ @"uAmbient": @0.06, @"uInkCap": @0.3, @"uRidgeInkStrength": @0.3, @"uHillshade": @0.15 };
}

static NSString *resource(NSString *name, NSString *type) {
    NSString *path = [[NSBundle mainBundle] pathForResource:name ofType:type inDirectory:@"peak-finder"];
    return [NSString stringWithContentsOfFile:path encoding:NSUTF8StringEncoding error:nil] ?: @"";
}

static double bearing(double lat, double lon, MSFPosition *to) {
    double phi1 = lat * M_PI / 180, phi2 = to.lat * M_PI / 180, dLon = (to.lng - lon) * M_PI / 180;
    double y = sin(dLon) * cos(phi2);
    double x = cos(phi1) * sin(phi2) - sin(phi1) * cos(phi2) * cos(dLon);
    return atan2(y, x) * 180 / M_PI;
}

static double distance(double lat, double lon, MSFPosition *to) {
    double dLat = (to.lat - lat) * M_PI / 180, dLon = (to.lng - lon) * M_PI / 180;
    double a = pow(sin(dLat / 2), 2) + cos(lat * M_PI / 180) * cos(to.lat * M_PI / 180) * pow(sin(dLon / 2), 2);
    return 2 * 6371008.8 * asin(sqrt(a));
}

@implementation MSFPeakFinderExample {
    id<MSFExampleHost> _host;
    MSFMassifMap *_map;
    MSFPropertyGroup *_terrain;
    MSFMassifObject *_view;
    MSFMassifSource *_dem;
    MSFPeakFinderSky *_sky;
    MSFSubscription *_peakClick;
    NSString *_summitsCss;
    // The viewpoint: Grenoble, 400 m up, looking east at Belledonne - rotation is minus the heading.
    double _lat, _lon, _eye, _rotation, _tilt, _ground;
    BOOL _hours;
    int _generation;
    NSString *_selectedName;
    NSString *_selectedEle;
    MSFPosition *_selectedPosition;
    NSString *_shown;
}

+ (NSString *)exampleId {
    return @"peak-finder";
}

- (void)startWithHost:(id<MSFExampleHost>)host {
    _host = host;
    _map = host.map;
    _lat = 45.1885;
    _lon = 5.7245;
    _eye = 400;
    _rotation = -100;
    _tilt = -4;
    _shown = @"";
    _summitsCss = resource(@"summits", @"mss");
    MSFMassifMap *map = _map;

    _dem = [map source:@"dem"
                  spec:[[[[MSFSpec of:@"persistent-cache"]
                      set:@"databasePath" value:[host cachePath:@"mapterhorn-dem.db"]]
                      set:@"capacity" value:@(200 * 1024 * 1024)]
                      set:@"source" value:[[[[MSFSpec of:@"http"]
                          set:@"url" value:@"https://tiles.mapterhorn.com/{z}/{x}/{y}.webp"]
                          set:@"maxZoom" value:@16]
                          set:@"metaData" value:[[MSFSpec object] set:@"dem_encoding" value:@"terrarium"]]]
                 error:nil];

    // The terrain, and everything decided when its meshes are built: geo-three's cut (subdivide
    // distance 70, levels to 17) and mesh, no stitching, drawn 173 km out. The picture is the
    // surface shader, so nothing is draped over it.
    MSFSpec *terrainSpec = [[MSFSpec of:@"terrain"] set:@"source" value:@"dem"];
    NSDictionary *terrainValues = @{
        @"autoFlattenTilt": @0, @"autoFlattenParallax": @0, @"meshResolution": @171,
        @"tileEdgeStitchingEnabled": @NO, @"subdivideDistance": @70, @"maxZoom": @17,
        @"viewDistance": @173000, @"meshCacheSize": @640, @"normalSampleDistance": @40,
        @"postProcessDownscale": @1, @"surfaceShaderSource": resource(@"relief-surface", @"glsl"),
        @"backgroundColor": @"#ffffff", @"sharedGroundEnabled": @NO, @"drapeFillsEnabled": @NO,
        @"drapeLinesEnabled": @NO, @"billboardOcclusionEnabled": @YES,
        @"billboardOcclusionTolerance": @0.15, @"maxTileZoomCoarsening": @4,
    };
    for (NSString *key in terrainValues) {
        [terrainSpec set:key value:terrainValues[key]];
    }
    _terrain = [map terrainWithSpec:terrainSpec error:nil];
    [surface() enumerateKeysAndObjectsUsingBlock:^(NSString *name, NSNumber *value, BOOL *stop) {
        [[map.options call:@"terrainOptions.setSurfaceParameter" args:@[ name, value ] error:nil] destroy];
    }];

    // The ink is a post-process over the frame, reading the terrain's depth. The renderer hangs off
    // the map VIEW, which the map registered under its own id.
    MSFMassifObject *effect = [map object:@"effect" objectId:@"relief"
                                     spec:[[[[MSFSpec of:@"postprocess"] set:@"name" value:@"relief"]
                                         set:@"fragmentShader" value:resource(@"relief-ink", @"glsl")]
                                         set:@"terrainDepthRequired" value:@YES]
                                    error:nil];
    [ink() enumerateKeysAndObjectsUsingBlock:^(NSString *name, NSNumber *value, BOOL *stop) {
        [[effect call:@"setFloatParameter" args:@[ name, value ] error:nil] destroy];
    }];
    _view = [MSFMassif find:@"view" objectId:map.options.objectId];
    [_view set:@"mapRenderer.postProcessEffect" value:effect];

    // No sky, no background pattern: the panorama is read against the paper.
    [map apply:[[[[MSFSpec object] set:@"skyColor" value:@"#00000000"] set:@"clearColor" value:@"#ffffff"]
                  set:@"labelPadding" value:@200]];
    [map set:@"backgroundBitmap" value:[NSNull null]];
    [map lightWithSpec:[[[MSFSpec of:@"light"] set:@"sunAzimuth" value:@315] set:@"sunAltitude" value:@45]
                 error:nil];

    // First person: the position IS the eye and a drag turns the view about it. A panorama looks at
    // the horizon, so the tilt range opens above it too (tilt 90 is straight down).
    [map apply:[[[MSFSpec object] set:@"freeRoamMode" value:@"FREE_ROAM_MODE_FIRST_PERSON"]
                  set:@"tiltRange" value:@[ @-90, @90 ]]];
    [self setFov:46];
    [self placeCamera];

    // THE SUMMIT NAMES: OpenMapTiles' mountain_peak, and a style that puts every name in one row
    // above the skyline. The sky's path goes under them, the sun and its times over them.
    [map source:@"peaks"
           spec:[[[[MSFSpec of:@"persistent-cache"]
               set:@"databasePath" value:[host cachePath:@"openfreemap.db"]]
               set:@"capacity" value:@(100 * 1024 * 1024)]
               set:@"source" value:[[[[MSFSpec of:@"http"]
                   set:@"url" value:@"https://tiles.openfreemap.org/planet/latest/{z}/{x}/{y}.pbf"]
                   set:@"maxZoom" value:@14]
                   set:@"HTTPHeaders" value:[[MSFSpec object] set:@"User-Agent" value:kUserAgent]]]
          error:nil];
    MSFMassifLayer *skyBelow = [[map addLayer:@"sky" spec:[MSFSpec of:@"celestial"] error:nil] moveTo:0];
    MSFMassifLayer *skyAbove = [map addLayer:@"sky.top" spec:[MSFSpec of:@"celestial"] error:nil];
    _sky = [[MSFPeakFinderSky alloc] initWithMap:map below:skyBelow above:skyAbove];
    [self standOnGround];

    [host button:@"North" action:^{
        [self turnTo:0];
    }];
    [host button:@"Look at" action:^{
        if (self->_selectedPosition) {
            [self turnTo:-bearing(self->_lat, self->_lon, self->_selectedPosition)];
        }
    }];
    [host button:@"Fly to" action:^{
        if (self->_selectedPosition) {
            [self flyTo:self->_selectedPosition];
        }
    }];
    [host toggle:@"Hours" on:NO action:^(BOOL on) {
        self->_hours = on;
    }];
    [host slider:@"eye height, m" min:0 max:4000 value:_eye action:^(float metres) {
        self->_eye = metres;
        [self->_terrain set:@"focusLift" value:@(metres)];
    }];
    [host slider:@"field of view" min:5 max:120 value:46 action:^(float degrees) {
        [self setFov:degrees];
    }];
    [self tick];
}

- (void)setFov:(double)degrees {
    [_map set:@"fieldOfViewY" value:@(degrees)];
    // The ridge term's tap spacing: radians per screen pixel.
    UIView *view = _map.view;
    double pixels = MAX(view.bounds.size.height * view.contentScaleFactor, 1);
    [[_map.options call:@"terrainOptions.setSurfaceParameter"
                   args:@[ @"uPixelAngle", @(degrees * M_PI / 180 / pixels) ] error:nil] destroy];
}

/** The eye stands focusLift over the ground under it, which the renderer keeps every frame. */
- (void)placeCamera {
    [[_view call:@"moveCameraTo"
            args:@[ [MSFPosition positionWithLng:_lon lat:_lat], @13, @(_rotation), @(_tilt) ]
           error:nil] destroy];
    [_terrain set:@"focusLift" value:@(_eye)];
}

- (void)turnTo:(double)rotation {
    _rotation = rotation;
    _tilt = _map.camera.currentTilt;
    [self placeCamera];
}

/** Standing on the summit, facing the way it was seen from. */
- (void)flyTo:(MSFPosition *)peak {
    _rotation = -bearing(_lat, _lon, peak);
    _lat = peak.lat;
    _lon = peak.lng;
    [self selectName:nil ele:nil position:nil];
    [self placeCamera];
    [self standOnGround];
}

/**
 * Placed again once the ground is known: an eye placed before the viewpoint's elevation arrived
 * stays where it was put until the camera next moves.
 */
- (void)standOnGround {
    [self withGround:^{
        [self placeCamera];
        [self rebuildPeaks];
    }];
}

/**
 * A new style per viewpoint, since the eye's altitude is baked into the names' rank; the selected
 * summit is a style parameter, set on the live one.
 */
- (void)rebuildPeaks {
    _generation++;
    NSString *styleId = [NSString stringWithFormat:@"peaks.style.%d", _generation];
    NSString *css = [NSString stringWithFormat:@"@eye_elevation: %ld;\n@label_band: %.3f;\n%@",
                     lround(_ground + _eye), [self labelBand], _summitsCss];
    MSFMassifObject *style = [_map style:styleId
                                    spec:[[MSFSpec of:@"mbvt"] set:@"cartocss"
                                        value:[[MSFSpec of:@"cartocss"] set:@"css" value:css]]
                                   error:nil];
    [style set:@"params.selected_peak" value:[self selectedKey]];
    MSFMassifLayer *layer = [_map addLayer:[NSString stringWithFormat:@"peaks.layer.%d", _generation]
                                      spec:[[[[[[MSFSpec of:@"vector"] set:@"source" value:@"peaks"]
                                          set:@"style" value:styleId] set:@"preloading" value:@YES]
                                          set:@"labelRenderOrder" value:@"VECTOR_TILE_RENDER_ORDER_LAST"]
                                          set:@"tileSubstitutionPolicy" value:@"TILE_SUBSTITUTION_POLICY_VISIBLE"]
                                     error:nil];
    [layer moveTo:_map.layerCount - 2];
    __weak MSFPeakFinderExample *weakSelf = self;
    _peakClick = [layer onFeatureClick:^(MSFVectorTileClickEvent *e) {
        NSString *name = [e property:@"name"];
        // The key is `[name] + '|' + [ele]` as the style writes it: a whole number without a decimal.
        double ele = [e propertyDouble:@"ele" defaultValue:NAN];
        if (name && e.position) {
            [weakSelf selectName:name ele:isnan(ele) ? nil : [@(ele) stringValue] position:e.position];
        }
    }];
    if (_generation > 1) {
        [_map removeLayer:[NSString stringWithFormat:@"peaks.layer.%d", _generation - 1]];
        [MSFMassif destroy:@"style" objectId:[NSString stringWithFormat:@"peaks.style.%d", _generation - 1]];
    }
}

/**
 * The row the names hang from, low enough for a name wrapped at 70 px, 13 px text at 45 degrees, to
 * fit under the bar - the Alpimaps app's row (look.mjs labelBand).
 */
- (double)labelBand {
    double height = _map.view.bounds.size.height;
    double width = 70 + 13 * 2.5 + 10;
    double row = width * sin(M_PI / 4) + (13 * 2.6 + 4) * cos(M_PI / 4) + 10;
    return height > 0 ? MIN(0.9, (_host.topInset + row) / height) : 0.2;
}

- (NSString *)selectedKey {
    return _selectedName ? [NSString stringWithFormat:@"%@|%@", _selectedName, _selectedEle ?: @""] : @"";
}

- (void)selectName:(NSString *)name ele:(NSString *)ele position:(MSFPosition *)position {
    _selectedName = name;
    _selectedEle = ele;
    _selectedPosition = position;
    [[MSFMassif style:[NSString stringWithFormat:@"peaks.style.%d", _generation]]
        set:@"params.selected_peak" value:[self selectedKey]];
    _shown = @"";
}

/** The heading, the rise and set, and the selected summit, refreshed as the view turns. */
- (void)tick {
    _rotation = _map.camera.currentRotation;
    _tilt = _map.camera.currentTilt;
    NSString *riseSet = [_sky updateLat:_lat lon:_lon eye:_eye hours:_hours];
    double heading = fmod(fmod(-_rotation, 360) + 360, 360);
    NSString *text = [NSString stringWithFormat:@"%ld° %@  ·  %@", lround(heading) % 360,
                      [MSFPeakFinderSky compass:heading], riseSet];
    if (_selectedPosition) {
        double toPeak = fmod(bearing(_lat, _lon, _selectedPosition) + 360, 360);
        text = [text stringByAppendingFormat:@"\n%@  ·  %@%.1f km  ·  %ld° %@", _selectedName,
                _selectedEle ? [_selectedEle stringByAppendingString:@" m  ·  "] : @"",
                distance(_lat, _lon, _selectedPosition) / 1000, lround(toPeak), [MSFPeakFinderSky compass:toPeak]];
    } else {
        text = [text stringByAppendingString:@"\nDrag to look around, tap a summit name."];
    }
    if (![text isEqualToString:_shown]) {
        _shown = text;
        [_host caption:text];
    }
    [_host after:0.2 run:^{
        [self tick];
    }];
}

/** The ground under the viewpoint, off the DEM tile itself: the names rank by the eye's altitude. */
- (void)withGround:(void (^)(void))then {
    int zoom = 12;
    double tiles = 1 << zoom;
    double x = (_lon + 180) / 360 * tiles;
    double phi = _lat * M_PI / 180;
    double y = (1 - log(tan(phi) + 1 / cos(phi)) / M_PI) / 2 * tiles;
    [_dem loadTileX:(int)x y:(int)y zoom:zoom completion:^(NSData *data) {
        UIImage *image = data ? [UIImage imageWithData:data] : nil;
        if (image.CGImage) {
            size_t width = CGImageGetWidth(image.CGImage), height = CGImageGetHeight(image.CGImage);
            unsigned char pixel[4] = { 0 };
            CGColorSpaceRef space = CGColorSpaceCreateDeviceRGB();
            CGContextRef context = CGBitmapContextCreate(pixel, 1, 1, 8, 4, space,
                                                         (CGBitmapInfo)kCGImageAlphaNoneSkipLast);
            // One pixel of context, with the image shifted so the wanted texel lands on it.
            CGContextDrawImage(context, CGRectMake(-floor(fmod(x, 1) * width),
                                                   -(height - 1 - floor(fmod(y, 1) * height)), width, height),
                               image.CGImage);
            CGContextRelease(context);
            CGColorSpaceRelease(space);
            self->_ground = pixel[0] * 256 + pixel[1] + pixel[2] / 256.0 - 32768;
        }
        then();
    }];
}

@end

code.js:
/**
 * A panorama drawn as peakfinder.com draws it: the terrain as ink on paper from a shader, every
 * summit named along the skyline, and the sun's path with its rise and set over the ridges. Drag to
 * look around, tap a name, then fly to it.
 */
import { find } from '@massif-maps/web';
import { INK_SHADER, LABEL, SURFACE_SHADER, labelBand, summitsStyle } from './peak-finder/look.mjs';
import { createChrome, toCompass } from './peak-finder/chrome.mjs';
import { createSky } from './peak-finder/sun.mjs';
import { demTiles, vectorTiles } from './shared.mjs';

// The ink pass: silhouettes only (operator 2), a heavier skyline. Uniforms left out read zero.
const INK = {
  uOperator: 2, uOutlineGain: 12, uOutlinePower: 1, uOutlineFloor: 0.008, uOutlineCeiling: 1, uOutlineWidth: 1,
  uIntensity: 0.8, uHorizonBoost: 0.9, uHorizonWidth: 2.5, uDepthThreshold: 1, uCreaseThreshold: 0.12,
  uRidgeStrength: 2, uRidgeThreshold: 0.05, uRidgeGroundSpan: 90, uDepthTexelSize: 2, uGrazingFloor: 0.15,
  uInkDistance: 50000, uMetersPerUnit: 40075016.68558 / (1 << 20), uSilhouetteGate: 865, uHazeDistance: 60000,
  uDistortCenterX: 0.5, uDistortCenterY: 0.5, uDistortScreenTanX: 1, uDistortScreenTanY: 1, uDistortRenderTanX: 1, uDistortRenderTanY: 1,
};
// The surface: ridge ink capped by the light, and a touch of hillshade after the cap.
const SURFACE = { uAmbient: 0.06, uInkCap: 0.3, uRidgeInkStrength: 0.3, uHillshade: 0.15 };

export default async function start(host) {
  const map = host.map;
  const query = new URLSearchParams(location.search);
  const num = (name, fallback) => (query.has(name) ? Number(query.get(name)) : fallback);
  // The viewpoint: Grenoble, 400 m up, looking east at Belledonne - rotation is minus the heading.
  const view = { lat: num('lat', 45.1885), lon: num('lon', 5.7245), eye: num('elevation', 400), rotation: num('rotation', -100), tilt: num('tilt', -4), fov: num('fov', 46) };
  const label = { ...LABEL };

  // The terrain, and everything decided when its meshes are built: geo-three's cut (subdivide
  // distance 70, levels to 17) and mesh, no stitching, drawn 173 km out.
  const terrain = map.terrain({
    type: 'terrain',
    source: demTiles(),
    autoFlattenTilt: 0, autoFlattenParallax: 0,
    meshResolution: 171, tileEdgeStitchingEnabled: false, subdivideDistance: 70, maxZoom: 17,
    viewDistance: 173000, meshCacheSize: 640, normalSampleDistance: 40, postProcessDownscale: 1,
    // The picture is the surface shader, so nothing is draped over it; the one layer is billboards.
    surfaceShaderSource: SURFACE_SHADER, backgroundColor: '#ffffff',
    sharedGroundEnabled: false, drapeFillsEnabled: false, drapeLinesEnabled: false,
    billboardOcclusionEnabled: true, billboardOcclusionTolerance: label.occlusion, maxTileZoomCoarsening: 4,
  });
  const terrainObject = map.child('terrainOptions');
  const setSurface = (name, value) => terrainObject.call('setSurfaceParameter', name, value);
  for (const [name, value] of Object.entries(SURFACE)) {
    setSurface(name, value);
  }

  // The ink is a post-process over the frame, reading the terrain's depth.
  map.camera();
  const mapView = find('view', `${map.id}:view`, 'massif::BaseMapView');
  const ink = map.object('effect', 'relief', {
    type: 'postprocess', name: 'relief', fragmentShader: INK_SHADER, terrainDepthRequired: true,
  });
  for (const [name, value] of Object.entries(INK)) {
    ink.call('setFloatParameter', name, value);
  }
  mapView.set('mapRenderer.postProcessEffect', ink.handle);

  // No sky, no background pattern: the panorama is read against the paper.
  map.child('skyOptions')?.set('enabled', false);
  map.apply({ skyColor: '#00000000', clearColor: '#ffffff', backgroundBitmap: 0, labelPadding: 200 });
  map.light({ type: 'light', sunAzimuth: 315, sunAltitude: 45 });

  // First person: the position IS the eye and a drag turns the view about it. A panorama looks at the
  // horizon, so the tilt range opens above it too (tilt 90 is straight down).
  map.apply({ freeRoamMode: 'FREE_ROAM_MODE_FIRST_PERSON', tiltRange: [-90, 90] });
  const setFov = (degrees) => {
    view.fov = degrees;
    map.set('fieldOfViewY', degrees);
    // The ridge term's tap spacing: radians per screen pixel.
    setSurface('uPixelAngle', (degrees * Math.PI / 180) / Math.max(host.root.clientHeight * devicePixelRatio, 1));
  };
  // The eye stands focusLift over the ground under it, which the renderer keeps every frame.
  const placeCamera = () => {
    mapView.call('moveCameraTo', [view.lon, view.lat, 0], 13, view.rotation, view.tilt);
    terrain.set('focusLift', view.eye);
  };
  setFov(view.fov);
  placeCamera();

  const chrome = createChrome(host.root, {
    north: () => turnTo(0),
    lookAt: () => selected && turnTo(-bearing(view, selected)),
    flyTo: () => selected && flyTo(selected),
    select: (peak) => select(peak),
  });
  const turnTo = (rotation) => {
    view.rotation = rotation;
    view.tilt = map.camera().tilt();
    placeCamera();
  };

  // THE SUMMIT NAMES, as the app draws them: OpenMapTiles' mountain_peak, and a style that puts every
  // name in one row above the skyline. The eye's altitude is baked into the style's rank, so a new
  // viewpoint is a new style - and the selected summit is a style parameter, set on the live one.
  const summits = map.source('peaks', vectorTiles());
  const skyBelow = map.add(map.buildLayer('sky', { type: 'celestial' }), 0);
  const skyAbove = map.addLayer('sky.top', { type: 'celestial' });
  let ground = await groundElevation(view);
  // Placed again once the ground is known: an eye placed before the viewpoint's elevation arrived
  // stays where it was put until the camera next moves.
  Object.assign(view, { rotation: map.camera().rotation(), tilt: map.camera().tilt() });
  placeCamera();
  let generation = 0;
  let current = null;
  let selectedKey = '';
  const rebuildPeaks = () => {
    generation += 1;
    label.band = labelBand(label, host.root.clientHeight);
    const css = summitsStyle(label, ground + view.eye);
    const style = map.style(`peaks.style.${generation}`, { type: 'mbvt', cartocss: { type: 'cartocss', css } });
    style.set('params.selected_peak', selectedKey);
    const layer = map.add(map.buildLayer(`peaks.layer.${generation}`, {
      type: 'vector', source: summits.handle, style: style.handle, preloading: true,
      labelRenderOrder: 'VECTOR_TILE_RENDER_ORDER_LAST', tileSubstitutionPolicy: 'TILE_SUBSTITUTION_POLICY_VISIBLE',
    }), map.layerCount() - 1);
    layer.onFeatureClick((e) => {
      const position = e.getPos('featurePos');
      const name = e.get('feature.properties.name');
      if (name && position) {
        select({ name, ele: e.get('feature.properties.ele'), lon: position[0], lat: position[1] });
      }
    });
    if (current) {
      map.removeLayer(current.layer);
      current.layer.destroy();
      current.style.destroy();
    }
    current = { layer, style };
  };
  rebuildPeaks();

  let selected = null;
  const select = (peak) => {
    selected = peak;
    selectedKey = peak ? `${peak.name}|${peak.ele ?? ''}` : '';
    current?.style.set('params.selected_peak', selectedKey);
    const km = peak ? distance(view, peak) / 1000 : 0;
    const heading = peak ? (bearing(view, peak) + 360) % 360 : 0;
    const height = peak?.ele ? `${Math.round(Number(peak.ele)).toLocaleString('en')} m  ·  ` : '';
    chrome.showPeak(peak, `${height}${km.toFixed(km < 10 ? 1 : 0)} km  ·  ${Math.round(heading)}° ${toCompass(heading)}`);
  };
  // Standing on the summit, facing the way it was seen from.
  const flyTo = async (peak) => {
    view.rotation = -bearing(view, peak);
    Object.assign(view, { lat: peak.lat, lon: peak.lon });
    select(null);
    ground = await groundElevation(view);
    placeCamera();
    rebuildPeaks();
  };

  const updateSky = createSky(map, terrainObject, skyBelow, skyAbove, (text) => chrome.showRiseSet(text));

  chrome.section('viewpoint');
  chrome.slider('eye height, m above the ground', view.eye, 0, 4000, 10, (metres) => {
    view.eye = metres;
    terrain.set('focusLift', metres);
  });
  chrome.slider('field of view', view.fov, 5, 120, 1, setFov);
  chrome.section('summit names');
  let rebuildTimer = 0;
  const relabel = (name) => (value) => {
    label[name] = value;
    clearTimeout(rebuildTimer);
    rebuildTimer = setTimeout(rebuildPeaks, 250);
  };
  chrome.choice('layout', label.layout, [['band', 'a row above the skyline'], ['top', 'a row at a fixed height'], ['skyline', 'over each summit']], relabel('layout'));
  chrome.slider('name angle', label.angle, 0, 90, 1, relabel('angle'));
  chrome.slider('text size', label.size, 8, 24, 0.5, relabel('size'));
  chrome.slider('how far behind a ridge a summit keeps its name', label.occlusion, 0, 1, 0.01, (value) => terrain.set('billboardOcclusionTolerance', value));
  chrome.finishPanel();

  const tick = () => {
    const camera = map.camera();
    view.rotation = camera.rotation();
    view.tilt = camera.tilt();
    chrome.showHeading(((-view.rotation % 360) + 360) % 360);
    updateSky({ ...view, ...chrome.sunState() });
    chrome.setPeakfinderLink(peakfinderUrl(view, ground, host.root));
    requestAnimationFrame(tick);
  };
  tick();
}

/** The ground under a viewpoint, off the DEM tile itself: the summit names rank by the eye's altitude. */
async function groundElevation({ lat, lon }) {
  try {
    const tiles = 2 ** 12;
    const x = (lon + 180) / 360 * tiles;
    const y = (1 - Math.log(Math.tan(lat * Math.PI / 180) + 1 / Math.cos(lat * Math.PI / 180)) / Math.PI) / 2 * tiles;
    const url = demTiles().source.url.replace('{z}', 12).replace('{x}', Math.floor(x)).replace('{y}', Math.floor(y));
    const bitmap = await createImageBitmap(await (await fetch(url)).blob());
    const context = new OffscreenCanvas(bitmap.width, bitmap.height).getContext('2d');
    context.drawImage(bitmap, 0, 0);
    const [r, g, b] = context.getImageData(Math.floor((x % 1) * bitmap.width), Math.floor((y % 1) * bitmap.height), 1, 1).data;
    return r * 256 + g + b / 256 - 32768;
  } catch (error) {
    return 0;
  }
}

const toRad = Math.PI / 180;
function bearing(from, to) {
  const y = Math.sin((to.lon - from.lon) * toRad) * Math.cos(to.lat * toRad);
  const x = Math.cos(from.lat * toRad) * Math.sin(to.lat * toRad) - Math.sin(from.lat * toRad) * Math.cos(to.lat * toRad) * Math.cos((to.lon - from.lon) * toRad);
  return Math.atan2(y, x) / toRad;
}
function distance(from, to) {
  const a = Math.sin((to.lat - from.lat) * toRad / 2) ** 2 + Math.cos(from.lat * toRad) * Math.cos(to.lat * toRad) * Math.sin((to.lon - from.lon) * toRad / 2) ** 2;
  return 2 * 6371008.8 * Math.asin(Math.sqrt(a));
}

/** The same view on peakfinder.com: its azimuth is a heading, its field of view horizontal. */
function peakfinderUrl(view, ground, root) {
  const fovX = 2 * Math.atan(Math.tan(view.fov * Math.PI / 360) * root.clientWidth / Math.max(root.clientHeight, 1)) / toRad;
  return 'https://www.peakfinder.com/?' + new URLSearchParams({
    lat: view.lat, lng: view.lon, ele: Math.round(ground), off: Math.round(view.eye), azi: -view.rotation, alt: view.tilt, fov: fovX.toFixed(2), cfg: 'es',
  }) + '&name';
}

/**
 * @title Hillshade
 * @section terrain
 * @order 50
 * Shaded relief computed on the fly from an elevation source and laid over the basemap: pick the
 * algorithm, scale the relief.
 */
import { demTiles, massifStyle, vectorTiles } from './shared.mjs';

const METHODS = ['IGOR', 'COMBINED', 'MULTIDIRECTIONAL', 'STANDARD', 'BASIC'];

export default async function start(host) {
  const map = host.map;
  map.addLayer('basemap', { type: 'vector', source: vectorTiles(), style: await massifStyle(map) });
  // heightScale 1 is the true slope, what MapLibre shades; the default is a twentieth of it.
  const hillshade = map.addLayer('hillshade', { type: 'hillshade', source: demTiles(), hillshadeMethod: METHODS[0], heightScale: 1 });
  map.camera().moveTo([5.83, 45.25], { zoom: 10.5 });

  let method = 0;
  host.button('Method', () => {
    method = (method + 1) % METHODS.length;
    hillshade.set('hillshadeMethod', METHODS[method]);
    host.caption(`${METHODS[method]} hillshade.`);
  });
  // A shader uniform: the relief changes without a tile being decoded again.
  host.slider('Exaggeration', 0, 3, 1, (value) => hillshade.set('exaggeration', value));
  host.caption('Chartreuse, Vercors and Belledonne, shaded from a terrarium DEM.');
}

/**
 * @title On-the-fly contour lines
 * @section terrain
 * @order 51
 * Contour lines traced from an elevation source at runtime, no contour tileset needed, and styled
 * with CartoCSS like any vector layer.
 */
import { demTiles, massifStyle, vectorTiles } from './shared.mjs';

// `div` is the largest round divisor of the elevation, so `div >= 100` picks the index lines.
const STYLE = `
#contour {
  line-color: #a0663a;
  line-opacity: 0.7;
  line-width: 0.6;
  [div >= 100] {
    line-width: 1.3;
    text-name: [ele] + ' m';
    text-face-name: 'Roboto';
    text-size: 10;
    text-fill: #7a4b28;
    text-halo-fill: #ffffffcc;
    text-halo-radius: 1.5;
    text-placement: line;
  }
}`;

export default async function start(host) {
  const map = host.map;
  map.addLayer('basemap', { type: 'vector', source: vectorTiles(), style: await massifStyle(map) });
  // The contour source wraps the DEM: the tiles are fetched and decoded once, for both.
  const contours = map.source('contours', { type: 'contour', source: demTiles(), baseInterval: 20 });
  map.addLayer('contours', { type: 'vector', source: 'contours', style: { type: 'mbvt', cartocss: { type: 'cartocss', css: STYLE } } });
  map.camera().moveTo([5.73, 45.215], { zoom: 13.5 });

  for (const interval of [10, 20, 50]) {
    // A live property: the source traces again, the layer is not rebuilt.
    host.button(`${interval} m`, () => {
      contours.set('baseInterval', interval);
      host.caption(`Every ${interval} m, multiplied per zoom band.`);
    });
  }
  host.caption('Contours over the Bastille and the Chartreuse, traced from a terrarium DEM.');
}

